function showDatabaseError(message){const status=$('#saved-state');if(status){status.title=message;status.innerHTML='<i></i> Database unavailable';status.classList.add('database-error')}}
function saveDatabaseState(){const snapshot=stateSnapshot();databaseSaveQueue=databaseSaveQueue.then(async()=>{const response=await fetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({state:snapshot})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Database save failed (${response.status})`);const status=$('#saved-state');if(status){status.title='All newsletter data is saved to the connected database.';status.innerHTML='<i></i> Database saved';status.classList.remove('database-error')}}).catch(error=>{console.error('[storage]',error);showDatabaseError(`Database save failed: ${error.message}. Browser cache is retained.`)})}
async function initializeDatabase(){try{const response=await fetch('/api/state'),data=await response.json();if(!response.ok)throw new Error(data.error||'Database is unavailable.');if(data.record?.state){const s=data.record.state;newsletters=s.newsletters||newsletters;issues=s.issues||issues;activity=s.activity||activity;media=s.media||media;issueRevisions=s.issueRevisions||issueRevisions;aiRuns=s.aiRuns||aiRuns}const migrated=migrateUneditedStarter();for(const [key,value] of Object.entries(stateSnapshot()))try{localStorage.setItem('ss-newsletter-'+key,JSON.stringify(value))}catch{}databaseReady=true;if(!data.record||migrated)saveDatabaseState();const status=$('#saved-state');if(status){status.title='Connected to the database. Newsletter data is saved there.';status.innerHTML='<i></i> Database connected';status.classList.remove('database-error')}}catch(error){console.error('[storage]',error);showDatabaseError(`${error.message} Existing browser data is still available on this device.`)}render()}
let pdfjsModule;
$('#draft-upload').addEventListener('change',async e=>{
 const file=e.target.files?.[0],status=$('#draft-upload-status');if(!file)return;
 status.textContent='Reading file…';status.classList.remove('upload-error');
 try{
  if(file.size>20*1024*1024)throw new Error('File is larger than 20 MB.');
  const ext=file.name.split('.').pop().toLowerCase();let text='';
  if(['txt','md'].includes(ext))text=await file.text();
  else if(ext==='docx'){
   if(!window.mammoth)throw new Error('The Word document reader did not load. Check your internet connection and retry.');
   const result=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});text=result.value;
  }else if(ext==='pdf'){
   pdfjsModule ||= await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@6.5.438/build/pdf.mjs');
   pdfjsModule.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@6.5.438/build/pdf.worker.mjs';
   const pdf=await pdfjsModule.getDocument({data:await file.arrayBuffer()}).promise,pages=[];
   for(let pageNo=1;pageNo<=pdf.numPages;pageNo++){const page=await pdf.getPage(pageNo),content=await page.getTextContent();pages.push(content.items.map(item=>item.str+(item.hasEOL?'\n':' ')).join('').trim())}
   text=pages.filter(Boolean).join('\n\n');
  }else if(ext==='doc')throw new Error('Legacy .doc files are not supported. Save the file as .docx and upload it again.');
  else throw new Error('Choose a PDF, .docx, .txt, or .md file.');
  text=text.trim();if(!text)throw new Error(ext==='pdf'?'No selectable text was found. This may be a scanned PDF; run OCR on it, then upload the searchable PDF.':'No text was found in this file.');
  const draft=$('#edit-content'),old=draft.value.trim();draft.value=old?`${draft.value.trimEnd()}\n\n${text}`:text;
  status.textContent=`Added ${file.name} · ${text.length.toLocaleString()} characters`;
 }catch(err){status.textContent=err.message||'Could not read this file.';status.classList.add('upload-error')}
 finally{e.target.value=''}
});
