function scheduleLabel(n){if(!n?.timezone)return n?.schedule||'';let time=n.publishTime||'09:00',hour=Number(time.slice(0,2)),minute=time.slice(3,5),ampm=hour>=12?'PM':'AM',display=`${hour%12||12}:${minute} ${ampm}`;return `Weekly · ${weekdayName(n.publishWeekday)} ${display} · ${n.timezone}`}
