function renderIssues(){let q=($('#issue-search')?.value||'').toLowerCase(),s=$('#status-filter')?.value||'all',n=$('#newsletter-filter')?.value||'all';let arr=issues.filter(i=>(s==='all'||(s==='active'?['Draft','In review','Approved'].includes(i.status):s==='attention'?(i.status==='In review'||!i.metaTitle||!i.imageName):i.status===s))&&(n==='all'||i.newsletterId===n)&&`${i.title} ${newsletter(i.newsletterId).name}`.toLowerCase().includes(q));$('#issue-rows').innerHTML=arr.length?arr.map(i=>issueRow(i,true)).join(''):'<tr><td colspan="6"><div class="empty-state">No issues match these filters.</div></td></tr>';$('#issue-count').textContent=`${arr.length} issue${arr.length===1?'':'s'}`}
function renderCalendar(){let y=calendarDate.getFullYear(),m=calendarDate.getMonth(),today=new Date(),todayString=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;$('#month-label').textContent=calendarDate.toLocaleDateString('en',{month:'long',year:'numeric'});let first=new Date(y,m,1),start=new Date(y,m,1-first.getDay()),cells=[];for(let x=0;x<42;x++){let d=new Date(start);d.setDate(start.getDate()+x);let ds=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,isToday=ds===todayString,dayIssues=issues.filter(i=>i.date===ds),issueEvents=dayIssues.map(i=>{let n=newsletter(i.newsletterId),time=i.scheduledAt?.slice(11,16)||n.publishTime||'',zone=i.scheduledTimezone||n.timezone||'local';return `<button class="calendar-event ${i.status==='Scheduled'?'is-scheduled':i.status==='Published'?'is-published':''}" data-edit-issue="${i.id}"><small>${esc(time)} &middot; ${esc(zone)}</small>${esc(i.title)}</button>`}),followups=issues.filter(i=>i.status==='Published'&&i.date).flatMap(i=>[7,28].map(offset=>addDays(i.date,offset)===ds?{id:i.id,title:i.title,label:offset===7?'7-day results check':'4-week editorial review'}:null).filter(Boolean));cells.push(`<div class="day-cell ${d.getMonth()!==m?'outside':''} ${isToday?'today':''}"><span class="day-number">${d.getDate()}</span>${issueEvents.join('')}${followups.map(f=>`<button class="calendar-event is-review" data-edit-issue="${f.id}"><small>${f.label}</small>${esc(f.title)}</button>`).join('')}</div>`)}$('#month-grid').innerHTML=['SUN','MON','TUE','WED','THU','FRI','SAT'].map(d=>`<div class="weekday">${d}</div>`).join('')+cells.join('')}
