function openIssue(id){let i=issues.find(x=>x.id===id);$('#issue-form').reset();$('#issue-id').value=i?.id||'';$('#dialog-title').textContent=i?'Edit issue':'New issue';$('#ai-result').hidden=true;$('#ai-result').innerHTML='';pendingSuggestion=null;pendingAiRunId=null;aiApplied=false;$('#edit-newsletter').value=i?.newsletterId||newsletters[0].id;let n=newsletter($('#edit-newsletter').value);if(i){$('#edit-title').value=i.title;$('#edit-format').value=i.format||'Article';$('#edit-meta-title').value=i.metaTitle||'';$('#edit-meta-description').value=i.metaDescription||'';$('#edit-content').value=i.content||'';$('#edit-date').value=i.scheduledAt||(i.date?`${i.date}T${n.publishTime||'09:00'}`:'');$('#edit-status').value=i.status;$('#dest-linkedin').checked=(i.destinations||[]).includes('LinkedIn');$('#dest-website').checked=(i.destinations||[]).includes('Company website');$('#metrics-live-url').value=i.liveUrl||'';$('#metrics-views').value=i.metrics?.views??'';$('#metrics-subscribers').value=i.metrics?.subscribers??'';$('#metrics-comments').value=i.metrics?.comments??'';$('#edit-alt').value=i.imageAlt||'';$('#source-url').value=i.sourceUrl||'';$('#subscription-cta').value=i.subscriptionCta||'';$('#publishing-checks').checked=Boolean(i.publishingChecks)}else{$('#edit-status').value='Draft';$('#edit-date').value=nextScheduleValue(n)}updateEditorGuidance();$('#issue-dialog').showModal()}
function openRules(id=''){let n=id?newsletter(id):null;$('#rules-form').reset();$('#rules-id').value=id;$('#rules-dialog-title').textContent=n?'Edit publication':'New newsletter concept';$('#save-rules').textContent=n?'Save settings':'Create concept';$('#rules-name').value=n?.name||'';$('#rules-region').value=n?.region||'';$('#rules-language').value=n?.language||'English';$('#rules-timezone').value=n?.timezone||'UTC';$('#rules-weekday').value=String(n?.publishWeekday??3);$('#rules-time').value=n?.publishTime||'09:00';$('#rules-guidance').value=n?.guidance||'';$('#rules-dialog').showModal()}
