$('#rules-form').addEventListener('submit',e=>{if(e.submitter?.id!=='save-rules')return;e.preventDefault();let id=$('#rules-id').value,n=id?newsletter(id):null,name=$('#rules-name').value.trim(),region=$('#rules-region').value.trim(),language=$('#rules-language').value.trim(),timezone=$('#rules-timezone').value.trim();try{new Intl.DateTimeFormat('en',{timeZone:timezone})}catch{alert('Enter a valid IANA timezone, such as Australia/Brisbane.');return}let values={name,region,language,timezone,publishWeekday:Number($('#rules-weekday').value),publishTime:$('#rules-time').value,guidance:$('#rules-guidance').value.trim()};if(n){Object.assign(n,values);n.schedule=scheduleLabel(n);log(`Updated publication settings for ${name}`)}else{let slug=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'newsletter',palette=['#8d78ff','#e4a66d','#bc7a9c','#62c4a0','#7595ff','#e5b860'];n={id:`${slug}-${Date.now().toString(36)}`,...values,mark:initials(name),accent:palette[newsletters.length%palette.length]};n.schedule=scheduleLabel(n);newsletters.push(n);log(`Created newsletter concept ${name}`)}persist('newsletters',newsletters);$('#rules-dialog').close();render()});
