$('#issue-form').addEventListener('submit',e=>{if(e.submitter?.id!=='save-issue')return;e.preventDefault();let id=$('#issue-id').value,existing=issues.find(i=>i.id===id),file=$('#edit-image').files[0],videoFile=$('#edit-video').files[0],status=$('#edit-status').value,n=newsletter($('#edit-newsletter').value),scheduledAt=$('#edit-date').value,words=wordCount($('#edit-content').value);if(['In review','Approved','Scheduled','Published'].includes(status)&&(words<450||words>1500)){alert(`This edition needs 450-1,500 words before it can move to ${status}. Current draft: ${words} words.`);return}if(status==='Published'&&existing?.status!=='Scheduled'&&existing?.status!=='Published'){alert('Publish only after the approved issue has been scheduled.');return}if(status==='Scheduled'){if(existing?.status!=='Approved'&&existing?.status!=='Scheduled'){alert('Get Monday approval first: save the issue as Approved, then schedule it.');return}if(!scheduledAt){alert('Choose the local publishing date and time first.');return}if(!(file||existing?.imageName)||!$('#edit-alt').value.trim()||!$('#source-url').value.trim()||!$('#subscription-cta').value.trim()||!$('#publishing-checks').checked){alert('Before scheduling, add a featured image with alt text, a factual source, a subscription CTA, and confirm the mobile/desktop publishing checks.');return}let day=new Date(`${scheduledAt.slice(0,10)}T00:00:00Z`).getUTCDay();if(day!==Number(n.publishWeekday)){alert(`${n.name} publishes on ${weekdayName(n.publishWeekday)} in ${n.timezone}. Choose that local day.`);return}}if(existing)recordRevision(existing,'manual','Before editor save');let obj={id:id||'i'+Date.now(),newsletterId:n.id,format:$('#edit-format').value,title:$('#edit-title').value.trim(),subtitle:existing?.subtitle||'',metaTitle:$('#edit-meta-title').value.trim(),metaDescription:$('#edit-meta-description').value.trim(),content:$('#edit-content').value,updated:'Just now',date:scheduledAt?scheduledAt.slice(0,10):'',scheduledAt:scheduledAt||'',scheduledTimezone:n.timezone||'UTC',status,destinations:[$('#dest-linkedin').checked?'LinkedIn':null,$('#dest-website').checked?'Company website':null].filter(Boolean),liveUrl:$('#metrics-live-url').value.trim(),metrics:{views:$('#metrics-views').value===''?null:Number($('#metrics-views').value),subscribers:$('#metrics-subscribers').value===''?null:Number($('#metrics-subscribers').value),comments:$('#metrics-comments').value===''?null:Number($('#metrics-comments').value)},imageAlt:$('#edit-alt').value.trim(),sourceUrl:$('#source-url').value.trim(),subscriptionCta:$('#subscription-cta').value.trim(),publishingChecks:$('#publishing-checks').checked,imageName:file?.name||existing?.imageName||'',coverImageAssetId:$('#cover-image-asset-id').value||existing?.coverImageAssetId||'',coverVideoName:videoFile?.name||existing?.coverVideoName||'',coverVideoSize:videoFile?.size||existing?.coverVideoSize||null,coverVideoAssetId:$('#cover-video-asset-id').value||existing?.coverVideoAssetId||''};if(existing)Object.assign(existing,obj);else issues.unshift(obj);recordRevision(obj,aiApplied?'ai_refinement':'manual',pendingAiRunId?`Accepted AI run ${pendingAiRunId}`:'Saved from editor');persist('issues',issues);log(`${existing?'Updated':'Created'} issue "${obj.title}" for ${n.name}`);$('#issue-dialog').close();render()});
$('#refine-button').onclick=async()=>{let btn=$('#refine-button'),result=$('#ai-result'),n=newsletter($('#edit-newsletter').value),draft=$('#edit-content').value.trim();if(!draft){result.hidden=false;result.innerHTML='<p class="ai-error">Add your draft content first, then ask AI to refine it.</p>';return}btn.disabled=true;btn.textContent='⟳ Refining draft…';result.hidden=false;result.innerHTML='<div class="ai-loading"><span class="spinner"></span><span>Reviewing the draft against the selected newsletter’s local guidance. This may take a little while.</span></div>';try{let response=await fetch('/api/refine',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:$('#edit-title').value,format:$('#edit-format').value,draft,newsletter:{name:n.name,region:n.region,language:n.language,guidance:n.guidance,seoGuidance:n.seoGuidance||''}})});let data=await response.json();if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);pendingSuggestion=data.suggestion;pendingAiRunId=crypto.randomUUID?crypto.randomUUID():`run-${Date.now()}`;aiRuns.unshift({id:pendingAiRunId,issueId:$('#issue-id').value||null,provider:data.provider,model:data.model,promptVersion:data.prompt_version,newsletterId:n.id,rulesSnapshot:{name:n.name,region:n.region,language:n.language,guidance:n.guidance},suggestion:data.suggestion,createdAt:new Date().toISOString()});aiRuns=aiRuns.slice(0,100);persist('aiRuns',aiRuns);let flags=data.suggestion.factual_flags.length?`<div class="ai-flags"><b>Verify these points</b><ul>${data.suggestion.factual_flags.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'';result.innerHTML=`<div class="ai-result-head"><span class="ai-badge">✦ ${esc(data.provider)}</span><span>${esc(data.model)}</span></div><h3>${esc(data.suggestion.content_title)}</h3><p class="ai-summary">${esc(data.suggestion.change_summary)}</p><details><summary>Preview revised draft and SEO fields</summary><div class="ai-preview-field"><b>Draft</b><pre>${esc(data.suggestion.revised_draft)}</pre></div><div class="ai-preview-field"><b>SEO title</b><p>${esc(data.suggestion.seo_meta_title)}</p></div><div class="ai-preview-field"><b>SEO description</b><p>${esc(data.suggestion.seo_meta_description)}</p></div></details>${flags}<div class="ai-result-actions"><button type="button" class="button secondary" data-ai-dismiss>Keep editing</button><button type="button" class="button primary" data-ai-apply>Apply suggestion</button></div>`;log(`AI generated a refinement suggestion for ${n.name}`)}catch(err){result.innerHTML=`<p class="ai-error">${esc(err.message)}<br><small>Check server configuration and the AI provider quota, then retry.</small></p>`}finally{btn.disabled=false;btn.innerHTML='✦ Refine with AI'}};
$('#edit-newsletter').addEventListener('change',()=>{$('#edit-date').value=nextScheduleValue(newsletter($('#edit-newsletter').value));updateEditorGuidance()});$('#edit-date').addEventListener('change',updateEditorGuidance);$('#edit-status').addEventListener('change',updateEditorGuidance);$('#edit-content').addEventListener('input',updateEditorGuidance);$('#issue-search').addEventListener('input',renderIssues);$('#status-filter').addEventListener('change',renderIssues);$('#newsletter-filter').addEventListener('change',renderIssues);$('#prev-month').onclick=()=>{calendarDate.setMonth(calendarDate.getMonth()-1);renderCalendar()};$('#next-month').onclick=()=>{calendarDate.setMonth(calendarDate.getMonth()+1);renderCalendar()};$('#today-button').onclick=()=>{let t=new Date();calendarDate=new Date(t.getFullYear(),t.getMonth(),1);renderCalendar()};$('#upload-button').onclick=()=>$('#image-upload').click();$('#image-upload').addEventListener('change',e=>{let f=e.target.files[0];if(!f)return;let reader=new FileReader();reader.onload=()=>{media.unshift({name:f.name,tag:`Uploaded - ${(f.size/1024).toFixed(0)} KB`,data:reader.result});persist('media',media);log(`Added image ${f.name} to media library`);renderMedia()};reader.readAsDataURL(f)});$('#clear-activity').onclick=()=>{if(confirm('Clear the local activity history?')){activity=[];persist('activity',activity);renderActivity()}};
