$('#generate-seo').addEventListener('click',async()=>{let button=$('#generate-seo'),status=$('#seo-ai-status'),draft=$('#edit-content').value.trim(),n=newsletter($('#edit-newsletter').value);if(draft.length<20){status.textContent='Add at least 20 characters of draft content first.';return}button.disabled=true;status.textContent='Generating a content title and SEO metadata…';try{let response=await fetch('/api/refine',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mode:'metadata',title:$('#edit-title').value,format:$('#edit-format').value,draft,newsletter:{name:n.name,region:n.region,language:n.language,guidance:n.guidance,seoGuidance:n.seoGuidance||''}})}),data=await response.json();if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);let suggestion=data.suggestion;$('#edit-title').value=suggestion.content_title;$('#edit-meta-title').value=suggestion.seo_meta_title.slice(0,70);$('#edit-meta-description').value=suggestion.seo_meta_description.slice(0,170);let runId=crypto.randomUUID?crypto.randomUUID():`run-${Date.now()}`;aiRuns.unshift({id:runId,issueId:$('#issue-id').value||null,provider:data.provider,model:data.model,promptVersion:`${data.prompt_version}-metadata`,newsletterId:n.id,rulesSnapshot:{name:n.name,region:n.region,language:n.language,guidance:n.guidance},suggestion,createdAt:new Date().toISOString()});aiRuns=aiRuns.slice(0,100);persist('aiRuns',aiRuns);log(`Generated an AI title and SEO metadata for ${n.name}`);status.textContent=`Generated by ${data.provider}. Review the fields, then save the issue.`}catch(error){status.textContent=error.message;console.error('[seo-ai]',error)}finally{button.disabled=false}});

const assetDbName='ss-newsletter-assets';
function openIssueAssetDb(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('This browser does not support local video storage.'));return}let request=indexedDB.open(assetDbName,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('assets'))request.result.createObjectStore('assets',{keyPath:'key'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('Could not open browser asset storage.'))})}
async function putIssueAsset(key,issueId,kind,file){let db=await openIssueAssetDb();return new Promise((resolve,reject)=>{let tx=db.transaction('assets','readwrite');tx.objectStore('assets').put({key,issueId,kind,fileName:file.name,mimeType:file.type||'',blob:file,updatedAt:new Date().toISOString()});tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{let error=tx.error;db.close();reject(error||new Error('Could not save the uploaded file.'))}})}
async function getIssueAsset(key){if(!key)return null;let db=await openIssueAssetDb();return new Promise((resolve,reject)=>{let tx=db.transaction('assets','readonly'),request=tx.objectStore('assets').get(key);request.onsuccess=()=>{db.close();resolve(request.result||null)};request.onerror=()=>{let error=request.error;db.close();reject(error||new Error('Could not read the saved file.'))}})}
async function deleteIssueAsset(key){if(!key)return;let db=await openIssueAssetDb();return new Promise((resolve,reject)=>{let tx=db.transaction('assets','readwrite');tx.objectStore('assets').delete(key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{let error=tx.error;db.close();reject(error||new Error('Could not remove the saved file.'))}})}
async function moveIssueAsset(fromKey,toKey){let asset=await getIssueAsset(fromKey);if(!asset)return;let db=await openIssueAssetDb();await new Promise((resolve,reject)=>{let tx=db.transaction('assets','readwrite');tx.objectStore('assets').put({...asset,key:toKey});tx.objectStore('assets').delete(fromKey);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{let error=tx.error;db.close();reject(error||new Error('Could not attach the uploaded file.'))}})}
function readIssueAssetAsDataUrl(blob){return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||new Error('Could not read the featured image.'));reader.readAsDataURL(blob)})}
const openIssueBeforeActions=openIssue;
let coverVideoPreviewUrl='';
openIssue=function(id){openIssueBeforeActions(id);$('#delete-issue').hidden=!id;$('#cover-image-asset-id').value='';$('#cover-video-asset-id').value='';$('#edit-video').value='';$('#edit-video-preview').hidden=true;$('#edit-video-preview').removeAttribute('src');if(coverVideoPreviewUrl){URL.revokeObjectURL(coverVideoPreviewUrl);coverVideoPreviewUrl=''}let issue=issues.find(item=>item.id===id);$('#video-upload-status').textContent=issue?.coverVideoName?`${issue.coverVideoName} · saved in this browser`:'MP4 video will be saved in this browser when you save the issue.';if(issue){$('#cover-image-asset-id').value=issue.coverImageAssetId||'';$('#cover-video-asset-id').value=issue.coverVideoAssetId||'';if(issue.coverVideoAssetId)getIssueAsset(issue.coverVideoAssetId).then(asset=>{if(asset&&$('#issue-id').value===id){coverVideoPreviewUrl=URL.createObjectURL(asset.blob);$('#edit-video-preview').src=coverVideoPreviewUrl;$('#edit-video-preview').hidden=false;$('#video-upload-status').textContent=`${asset.fileName} · ready for LinkedIn upload`}}).catch(error=>{$('#video-upload-status').textContent=`Saved video is unavailable in this browser: ${error.message}`})}};
$('#edit-video').addEventListener('change',e=>{let file=e.target.files?.[0],status=$('#video-upload-status'),preview=$('#edit-video-preview');if(!file)return;if(file.type!=='video/mp4'&&!file.name.toLowerCase().endsWith('.mp4')){e.target.value='';status.textContent='Choose an MP4 video file.';return}if(coverVideoPreviewUrl)URL.revokeObjectURL(coverVideoPreviewUrl);coverVideoPreviewUrl=URL.createObjectURL(file);preview.src=coverVideoPreviewUrl;preview.hidden=false;status.textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)} MB · save the issue to attach`});
let savingCoverAssets=false,allowCoverAssetSubmit=false;
$('#issue-form').addEventListener('submit',async e=>{if(e.submitter?.id!=='save-issue')return;if(allowCoverAssetSubmit){allowCoverAssetSubmit=false;return}let imageFile=$('#edit-image').files?.[0],videoFile=$('#edit-video').files?.[0],files=[['image',imageFile],['video',videoFile]].filter(([,file])=>file);if(!files.length)return;e.preventDefault();e.stopImmediatePropagation();if(savingCoverAssets)return;savingCoverAssets=true;let wasExisting=Boolean($('#issue-id').value),issueId=$('#issue-id').value||`i${Date.now()}`,pending=files.map(([kind,file])=>({kind,file,tempKey:`pending-${crypto.randomUUID?crypto.randomUUID():Date.now()}-${kind}`,assetId:`${issueId}-${kind}-${Date.now()}`}));$('#issue-id').value=issueId;for(let item of pending)$('#cover-'+(item.kind==='image'?'image':'video')+'-asset-id').value=item.assetId;if(videoFile&&videoFile.type!=='video/mp4'&&!videoFile.name.toLowerCase().endsWith('.mp4')){e.target.querySelector('#video-upload-status').textContent='Choose an MP4 video file.';savingCoverAssets=false;return}if(videoFile)$('#video-upload-status').textContent='Saving the video in this browser…';try{await Promise.all(pending.map(item=>putIssueAsset(item.tempKey,issueId,item.kind,item.file)));allowCoverAssetSubmit=true;$('#issue-form').requestSubmit($('#save-issue'));setTimeout(async()=>{let saved=issues.find(item=>item.id===issueId),allSaved=true;for(let item of pending){let linked=saved?.[item.kind==='image'?'coverImageAssetId':'coverVideoAssetId']===item.assetId;if(linked){try{await moveIssueAsset(item.tempKey,item.assetId)}catch(error){allSaved=false;console.error('[assets]',error)}}else{allSaved=false;deleteIssueAsset(item.tempKey).catch(error=>console.warn('[assets]',error))}}if(!allSaved){if(!wasExisting){$('#issue-id').value='';$('#cover-image-asset-id').value='';$('#cover-video-asset-id').value=''}if(videoFile)$('#video-upload-status').textContent='The issue was not saved. Check required fields, then retry the video upload.'}else if(videoFile)$('#video-upload-status').textContent=`${videoFile.name} · saved in this browser for LinkedIn upload`;savingCoverAssets=false},0)}catch(error){await Promise.all(pending.map(item=>deleteIssueAsset(item.tempKey).catch(()=>{})));if(!wasExisting){$('#issue-id').value='';$('#cover-image-asset-id').value='';$('#cover-video-asset-id').value=''}if(videoFile)$('#video-upload-status').textContent=`Video could not be saved: ${error.message}`;else alert(`Featured image could not be saved: ${error.message}`);savingCoverAssets=false}},true);
$('#edit-image').addEventListener('change',e=>{if(e.target.files?.[0])$('#cover-image-asset-id').value=`${$('#issue-id').value||'new'}-image-${Date.now()}`});
function deleteIssue(id){let issue=issues.find(item=>item.id===id);if(!issue)return;if(!confirm(`Delete "${issue.title}" and its saved revisions, AI drafts, and cover assets? This cannot be undone.`))return;issues=issues.filter(item=>item.id!==id);delete issueRevisions[id];aiRuns=aiRuns.filter(run=>run.issueId!==id);persist('issues',issues);persist('issueRevisions',issueRevisions);persist('aiRuns',aiRuns);for(let key of [issue.coverImageAssetId,issue.coverVideoAssetId])if(key)deleteIssueAsset(key).catch(error=>console.warn('[assets]',error));log(`Deleted issue "${issue.title}"`);if($('#issue-dialog').open&&$('#issue-id').value===id)$('#issue-dialog').close();render()}
async function downloadEditorPdf(){let n=newsletter($('#edit-newsletter').value),issue=issues.find(item=>item.id===$('#issue-id').value),title=$('#edit-title').value.trim()||'Untitled issue',draft=$('#edit-content').value.trim(),metaTitle=$('#edit-meta-title').value.trim(),metaDescription=$('#edit-meta-description').value.trim(),date=$('#edit-date').value,status=$('#edit-status').value,source=$('#source-url').value.trim(),cta=$('#subscription-cta').value.trim(),imageName=$('#edit-image').files[0]?.name||issue?.imageName||'',filename=title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'newsletter-issue',paragraphs=draft?draft.split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join(''):'<p class="empty">No draft content has been added.</p>',schedule=date?`${esc(date.replace('T',' '))} ${esc(n.timezone||'')}`:'Not scheduled',popup=window.open('','_blank');if(!popup){alert('Allow pop-ups for this site to export the issue as a PDF.');return}let imageData='';try{let selectedImage=$('#edit-image').files[0];if(selectedImage)imageData=await readIssueAssetAsDataUrl(selectedImage);else if(issue?.coverImageAssetId){let asset=await getIssueAsset(issue.coverImageAssetId);if(asset?.blob)imageData=await readIssueAssetAsDataUrl(asset.blob)}if(!imageData){let libraryImage=media.find(item=>item.name===imageName&&item.data);imageData=libraryImage?.data||''}}catch(error){console.warn('[pdf]',error)}let featuredImage=imageData?`<img class="featured-image" src="${imageData}" alt="${esc($('#edit-alt').value||'Featured image')}"/>`:'';let html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${esc(filename)}</title><style>@page{size:auto;margin:18mm}*{box-sizing:border-box}body{max-width:760px;margin:36px auto;padding:0 28px;color:#20242d;font:11pt/1.65 Georgia,"Times New Roman",serif}header{border-bottom:2px solid #252a35;padding-bottom:16px;margin-bottom:26px}.featured-image{display:block;width:100%;max-height:250px;object-fit:cover;border-radius:8px;margin:0 0 22px}.brand{font:700 9pt Arial,sans-serif;letter-spacing:2px;color:#6051aa;text-transform:uppercase}.kicker{font:700 8pt Arial,sans-serif;letter-spacing:1.5px;color:#727989;text-transform:uppercase;margin-top:26px}h1{font:700 27pt/1.15 Georgia,serif;margin:8px 0 12px;color:#161923}h2{font:700 10pt Arial,sans-serif;letter-spacing:.6px;text-transform:uppercase;margin:24px 0 7px;color:#4e5563}.meta{font:9pt/1.6 Arial,sans-serif;color:#636b78}.meta-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 22px;padding:14px 0;border-bottom:1px solid #d9dce2}.body-copy p{margin:0 0 13px;white-space:normal;overflow-wrap:anywhere}.small{font:9pt/1.5 Arial,sans-serif;color:#545b68;overflow-wrap:anywhere}.empty{color:#777;font-style:italic}@media screen{body{padding-bottom:40px}}</style></head><body>${featuredImage}<header><div class="brand">Savvy Signature · ${esc(n.name)}</div><div class="kicker">${esc(status)} · Issue draft</div><h1>${esc(title)}</h1>${issue?.subtitle?`<div class="meta">${esc(issue.subtitle)}</div>`:''}</header><div class="meta-grid"><div><b>Publication</b><br>${esc(n.name)} · ${esc(n.region||'')}</div><div><b>Format</b><br>${esc($('#edit-format').value||'Article')}</div><div><b>Scheduled</b><br>${schedule}</div><div><b>SEO meta title</b><br>${esc(metaTitle||'Not set')}</div><div><b>Featured image</b><br>${esc(imageName||'Not set')}</div><div><b>LinkedIn cover video</b><br>${esc(issue?.coverVideoName||$('#edit-video').files[0]?.name||'Not set')}</div></div><h2>SEO description</h2><div class="small">${esc(metaDescription||'Not set')}</div><h2>Draft</h2><main class="body-copy">${paragraphs}</main>${source?`<h2>Source / local example</h2><div class="small">${esc(source)}</div>`:''}${cta?`<h2>Subscription call to action</h2><div class="small">${esc(cta)}</div>`:''}</body></html>`;popup.document.open();popup.document.write(html);popup.document.close();popup.document.title=filename;let printed=false,printOnce=()=>{if(printed||popup.closed)return;printed=true;popup.focus();popup.print()};popup.addEventListener('load',()=>setTimeout(printOnce,100),{once:true});setTimeout(printOnce,800)}
$('#download-issue-pdf').addEventListener('click',downloadEditorPdf);
$('#delete-issue').addEventListener('click',()=>deleteIssue($('#issue-id').value));
document.addEventListener('click',e=>{let button=e.target.closest('[data-delete-issue]');if(button){e.preventDefault();e.stopPropagation();deleteIssue(button.dataset.deleteIssue)}});
